-- Huttopia Europe (europe.huttopia.com), researched 2026-09-30.
-- Inserts 63 Europe destinations missing from all_sage_data (Americas already present).
-- One property shell per destination + sibling rows for named accommodation types.
-- research_status left as table default (in_progress). quantity_of_units NULL (unpublished).
-- Pitches / motorhome stopovers omitted. Sources: LocalBusiness JSON-LD + destination pages.

BEGIN;

-- Brand: keep existing Americas website_url if set; document Europe regional site.
UPDATE public.glamping_brands
SET
  website_url = COALESCE(NULLIF(website_url, ''), 'https://europe.huttopia.com/en/'),
  notes = CASE
    WHEN COALESCE(notes, '') LIKE '%Europe regional site https://europe.huttopia.com/en/%' THEN notes
    ELSE COALESCE(notes, '') || E'\n\n[2026-09-30] Europe regional site https://europe.huttopia.com/en/ — 63 /en/site/ destinations inserted into all_sage_data (France 54, Spain 3, Netherlands 3, Belgium 2, Portugal 1). Americas: https://americas.huttopia.com/en/.'
  END,
  updated_at = now()
WHERE id = '7b37a1a6-e88e-41f2-943c-bd96d013100a'::uuid
   OR slug = 'huttopia';

